// Mirrors protocol/src/show.rs (shared by the app's local database and the cloud API).
// Ids are UUID strings generated by whoever creates the entity.

export type MemberRole = "owner" | "editor" | "commenter" | "viewer";

export interface Show {
    id: string;
    name: string;
    time: number;
    /** The signed-in user's role in this show. */
    role: MemberRole;
}

export interface ShowRole {
    id: string;
    show_id: string;
    name: string;
}

export interface ScenarioLine {
    id: string;
    /** Fractional ordering key: compare as plain strings (see `compareLines`). */
    position: string;
    name: string;
    note: string;
    duration: number;
    absolute_time: number | null;
}

export interface ScenarioLineComment {
    id: string;
    line_id: string;
    role_id: string | null;
    comment: string;
}

export interface ShowDetails {
    show: Show;
    roles: ShowRole[];
    lines: ScenarioLine[];
    comments: ScenarioLineComment[];
    /** The last change included (0 for a show that never synced). */
    rev: number;
}

/**
 * Script order: by `position`, ties (concurrent inserts) broken by id. Plain code-unit
 * comparison on purpose: `localeCompare` would order 'a' next to 'A' and scramble the script.
 */
export function compareLines(a: Pick<ScenarioLine, "id" | "position">, b: Pick<ScenarioLine, "id" | "position">): number {
    if (a.position !== b.position) return a.position < b.position ? -1 : 1;
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

/** What a member may do (protocol::show::MemberRole). The server enforces it regardless. */
export const canEditContent = (role: MemberRole): boolean => role === "owner" || role === "editor";
export const canComment = (role: MemberRole): boolean => canEditContent(role) || role === "commenter";
export const canManageShow = (role: MemberRole): boolean => role === "owner";

/** General comments (no role) first, then by the order the roles were listed in. */
export function sortCommentsByRole(comments: ScenarioLineComment[], roles: ShowRole[]): ScenarioLineComment[] {
    const rank = (comment: ScenarioLineComment): number =>
        comment.role_id === null ? -1 : roles.findIndex(role => role.id === comment.role_id);
    return [...comments].sort((a, b) => rank(a) - rank(b));
}
